    route: String,
    effective_thinking: String,
}
impl LiveLegState {
    fn new() -> Self {
        Self(Arc::new(StdRwLock::new(LiveLegSnapshot {
            route: OPERATOR.to_owned(),
            effective_thinking: String::new(),
        })))
    }

    pub fn route(&self) -> String {
        self.0
            .read()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
